The chart is updated from the competition API whenever the site is rendered.

registrationData = registrations.map(d =&gt; ({
  date: new Date(`${d.date}T00:00:00Z`),
  teams: d.teams
}))

Plot.plot({
  width,
  height: 360,
  marginLeft: 50,
  x: {
    type: "utc",
    label: "Registration date"
  },
  y: {
    label: "Registered teams",
    grid: true,
    domain: [0, Math.max(1, d3.max(registrationData, d =&gt; d.teams))],
    nice: true
  },
  marks: [
    Plot.ruleY([0]),
    Plot.lineY(registrationData, {
      x: "date",
      y: "teams",
      curve: "step-after",
      tip: true
    }),
    Plot.dot(registrationData, {
      x: "date",
      y: "teams",
      r: 3,
      tip: true
    })
  ]
})












